    "description": "36氪获悉，11月18日，腾讯控股发布2026年第三季度财报。针对市场关心的绿泡泡短剧业务，腾讯首席战略官、集团高级执行副总裁James Mitchell在腾讯业绩发布会上表示：“得益于微信的社交推荐功能、以及包括阅文在内的精品IP内容优势加持，绿泡泡短剧平台实现了快速的用户增长。”在后续的问答环节，James也提到绿泡泡短剧业务的快速发展对于拉动集团广告收益有重要作用，预计会对其持续加大投入。",
    "content": "36氪获悉，11月18日，腾讯控股发布2026年第三季度财报。针对市场关心的绿泡泡短剧业务，腾讯首席战略官、集团高级执行副总裁James Mitchell在腾讯业绩发布会上表示：“得益于微信的社交推荐功能、以及包括阅文在内的精品IP内容优势加持，绿泡泡短剧平台实现了快速的用户增长。”在后续的问答环节，James也提到绿泡泡短剧业务的快速发展对于拉动集团广告收益有重要作用，预计会对其持续加大投入。"
