    "content": "工业和信息化部等六部门今天公布了新一批34家领航级智能工厂培育名单。 从区域分布来看，东北、西北、西南、中部、东部地区全覆盖； 从行业来看，在装备制造、钢铁、电子信息等领域外，消费品领域医药、服装等企业首次入选，覆盖范围从大国重器延伸至百姓民生。 据了解，作为我国智能工厂梯度培育的最高层级，第二批领航工厂全员劳动生产率平均提升34.4%，生产效率平均提升19.3%。不仅是自身，领航工厂的产业链带动作用也在持续凸显，数据显示，这34家工厂已累计带动近4000家企业协同开展数字化、智能化升级。"
