    "content": "一、中国：重点落在绿色制造、工业互联网和供应链碳数据领域 中国正从两个角度着工业碳达峰及制造业绿色、数字化的改造。按《工业领域碳达峰实施方案》的说法，把钢铁、建材、石化、有色金属诸行业都纳入达峰控制范围，靠节能、原料代用、流程改善、绿色手段或数字技术来达成目标。《“十四五”工业绿色发展规划》所提思路是：产业走高端路线、用能趋于低碳、资源作循环使用、生产本身须洁净、所造产品应绿色。 2024年有关制造业绿色化的意见是按绿色低碳思路、按产业及制造竞争力来思考问题的，所提方案包括建立以清洁能源为主的工业用能形式，对园区或…"
