    "pub_date": "2026-11-19 11:22:37",
    "author": "",
    "description": "吃时令的东西，逛熟悉的街巷，偶尔为生计发愁，也不耽误找点乐子——喜欢“么么黑”的读者，大概都懂这只小黑猫踏实过日子的趣味。它没有什么了不起的冒险，却让人看着看着便笑了，原来自己的心事，也在这只猫的日常里。 借《8424的夏天》《人间存一角》两册十年精选集出版之机，本期上海书评播客邀请“么么黑”的创作者、画家张乐陆，聊聊“么么黑”的生活，也聊聊画猫的人。从平面设计、商业摄影到以画为日记，从镜头下幽暗的街角到画纸上有滋有味的上海，同一双眼睛…",
    "content": "吃时令的东西，逛熟悉的街巷，偶尔为生计发愁，也不耽误找点乐子——喜欢“么么黑”的读者，大概都懂这只小黑猫踏实过日子的趣味。它没有什么了不起的冒险，却让人看着看着便笑了，原来自己的心事，也在这只猫的日常里。 借《8424的夏天》《人间存一角》两册十年精选集出版之机，本期上海书评播客邀请“么么黑”的创作者、画家张乐陆，聊聊“么么黑”的生活，也聊聊画猫的人。从平面设计、商业摄影到以画为日记，从镜头下幽暗的街角到画纸上有滋有味的上海，同一双眼睛，如何看见日常的不同面貌？十年间，那些私人的片刻，又怎样成为读者熟悉而亲切的陪伴…"
