    "content": "美国总统特朗普在中国受到热情接待后表示，他星期四（11月19日）与中国国家主席习近平和俄罗斯总统普京的三方会晤，尚未举行就已是一场“胜利”（win）。 据路透社报道，特朗普接受福克斯新闻频道采访时，夸耀自己抵达中国时受到的隆重接待。相比之下，包括普京在内的其他领导人受到的接待则较为低调， 日本首相高市早苗抵达时则没有举行欢迎仪式 。 亚太经合组织（APEC）成员经济体领导人和代表星期三（18日）陆续抵达深圳，特朗普和高市都在当天下午抵步。 习近平今年9月访美时，特朗普曾亲自到机场迎接，中国此次以对等方式回礼。根据现…"
