    "description": "在河南省漯河市舞阳县泥河洼滞洪区，小麦播种已近尾声。 受台风“白海豚”影响，河南省于2026年8月13日启用泥河洼滞洪区，区内12.5万亩农田受灾。 洪水退去后，当地集中力量、分类施策，统筹推进受灾秸秆综合利用和农田深耕复耕工作，确保小麦适时播种。 记者在大田里看到，部分刚具备播种条件的地块上，种植户驾驶农机往来忙碌，力争在下一场雨水来临前完成播种。 记者：尚昆仑 新华社音视频部制作",
