    "description": "中新网11月19日电 据中国驻赞比亚使馆微信公众号消息，近日，16名中国公民在赞比亚穆钦加省因无证非法开采和加工黄金，污染当地河流，被赞有关安全和执法部门逮捕。赞矿业监管部门早前在发现有关情况后，已向涉事人员下达停业整顿令，但其无视禁令继续开采，最终酿成严重后果。",
