    "description": "新华社科威特城11月18日电（记者尹炣）第49届科威特国际书展18日在科威特米什里夫国际会展中心开幕。中国展区展出500余种图书，重点展示中国和科威特文学作品互译出版成果。 本届书展以“我们阅读，我们提升”为主题，由卡塔尔担任主宾国。共有来自34个国家和地区的592家机构参展，展出近25万种图书。 中国展区由科威特中国文化中心和五洲传播出版社联合设立，共展出图书800余册，外文版约占八成，以阿拉伯文版和英文版为主。展出图书涵盖中国政治、…",
    "content": "新华社科威特城11月18日电（记者尹炣）第49届科威特国际书展18日在科威特米什里夫国际会展中心开幕。中国展区展出500余种图书，重点展示中国和科威特文学作品互译出版成果。 本届书展以“我们阅读，我们提升”为主题，由卡塔尔担任主宾国。共有来自34个国家和地区的592家机构参展，展出近25万种图书。 中国展区由科威特中国文化中心和五洲传播出版社联合设立，共展出图书800余册，外文版约占八成，以阿拉伯文版和英文版为主。展出图书涵盖中国政治、文学、历史文化、人文社科及中文学习等领域。此外，展区还集中展示“中科经典和当代文…"
