    "title": "床位总量下行，养老院还进得去吗",
    "link": "https://www.chinanews.com.cn/sh/2026/11-19/10734527.shtml",
    "pub_date": "2026-11-19 10:36:48",
    "author": "",
    "description": "过去很长一段时间，养老床位在增加，养老机构在扩张，“到了晚年有没有一张养老院的床”似乎不是一个需要认真考虑的问题。但《2025年度国家老龄事业发展公报》(以下简称《公报》)给出的数字，让这个问题又浮出水面。",
