    "description": "随着竞争对手Anthropic即将上市，OpenAI首席执行官兼联合创始人奥尔特曼周三表示，OpenAI也在继续推进自身的IPO计划。“我们计划上市，”奥尔特曼在DealBook峰会上表示，并补充说“有许多理由表明这是正确的决定”。当被问及英伟达创始人兼前首席执行官黄仁勋的离职时，奥尔特曼称，“很难想象没有黄仁勋的人工智能行业。”（财联社）",
