    "title": "吉林冬天的快乐，已经开始加载",
    "link": "http://www.news.cn/20261119/9f5f7aa0de1243c58e081ef63ab595bf/c.html",
    "pub_date": "2026-11-19 10:24:15",
    "author": "",
    "description": "新华社长春11月19日电（记者邵美琦）降温了！下雪了！开板了！熟悉的快乐又回来了！ 连日来，随着吉林新雪季拉开帷幕，雪友们奔走相告，赶赴冰雪之约。有人顶门冲向雪道，抢先体验第一滑；有人举起手机，定格冬日美景；还有人已经开始盘算，先去解锁哪些新玩法。 而吉林的冬天，正在热气腾腾、源源不断地“上新”。 从长白山到北大湖、松花湖，从通化万峰到长春各大雪场，吉林各地雪场纷纷升级：雪道扩容、索道升级，交通接驳更加便利，滑雪之外的玩法也越来越丰富。…",
    "content": "新华社长春11月19日电（记者邵美琦）降温了！下雪了！开板了！熟悉的快乐又回来了！ 连日来，随着吉林新雪季拉开帷幕，雪友们奔走相告，赶赴冰雪之约。有人顶门冲向雪道，抢先体验第一滑；有人举起手机，定格冬日美景；还有人已经开始盘算，先去解锁哪些新玩法。 而吉林的冬天，正在热气腾腾、源源不断地“上新”。 从长白山到北大湖、松花湖，从通化万峰到长春各大雪场，吉林各地雪场纷纷升级：雪道扩容、索道升级，交通接驳更加便利，滑雪之外的玩法也越来越丰富。 11月13日，北大湖滑雪度假区正式开板。新雪季，雪道由74条增至81条，总长度…"
