    "pub_date": "2026-11-19 10:17:38",
    "author": "",
    "description": "新华社纽约11月18日电（记者刘亚南）美国联邦储备委员会18日公布10月货币政策会议纪要。纪要显示，尽管多数与会官员当时支持维持基准利率区间不变，但几乎所有官员认为，未来数月进一步加息可能是合适的。部分官员还提出，如果通胀数据不利，不排除一次加息超过25个基点。 纪要显示，部分美联储官员认为，美国通胀仍处高位且缺乏明显消退迹象，而当前货币政策的限制性不足。若推迟加息，高通胀可能根深蒂固，或迫使美联储未来采取幅度更大、冲击性更强的紧缩措施…",
    "content": "新华社纽约11月18日电（记者刘亚南）美国联邦储备委员会18日公布10月货币政策会议纪要。纪要显示，尽管多数与会官员当时支持维持基准利率区间不变，但几乎所有官员认为，未来数月进一步加息可能是合适的。部分官员还提出，如果通胀数据不利，不排除一次加息超过25个基点。 纪要显示，部分美联储官员认为，美国通胀仍处高位且缺乏明显消退迹象，而当前货币政策的限制性不足。若推迟加息，高通胀可能根深蒂固，或迫使美联储未来采取幅度更大、冲击性更强的紧缩措施。绝大多数美联储官员指出，能源价格高企持续推升通胀，另有部分官员把人工智能基础设…"
