    "content": "美国总统特朗普星期三（11月18日）抵达中国深圳出席亚太经合组织（APEC）领导人非正式会议，随行的美国电动车巨头特斯拉（Tesla）创办人马斯克被拍到乘坐美方代表团巴士。 据网媒“香港01”报道，现场视频显示，美方车队星期三驶往特朗普下榻的深圳东海朗廷酒店时，马斯克被拍到坐在代表团巴士内。 美国官员此前透露，此次深圳之行马斯克将随行，但不会参与三方会晤。 白宫随行记者团星期一（16日）在社交平台X披露的行程显示，特朗普星期四将先出席APEC会议，再到麒麟山庄与中国国家主席习近平举行双边会晤，随后参与中美俄元首会晤…"
