    "description": "新华社海口11月19日电 题：44只长臂猿见证海南热带雨林国家公园建设成效 新华社记者王存福 全球现存的20种长臂猿分布在亚洲11个国家，普遍面临种群衰退的威胁，而生活在海南热带雨林中的海南长臂猿截至2025年底恢复至7群44只，是全球唯一实现种群数量持续增长的长臂猿物种。上个月，以这片雨林为主体的海南热带雨林国家公园迎来正式设立五周年。 11月18日至22日，以“全球瑰宝·共享未来”为主题的2026热带雨林生态伙伴大会在海南海口举行，…",
    "content": "新华社海口11月19日电 题：44只长臂猿见证海南热带雨林国家公园建设成效 新华社记者王存福 全球现存的20种长臂猿分布在亚洲11个国家，普遍面临种群衰退的威胁，而生活在海南热带雨林中的海南长臂猿截至2025年底恢复至7群44只，是全球唯一实现种群数量持续增长的长臂猿物种。上个月，以这片雨林为主体的海南热带雨林国家公园迎来正式设立五周年。 11月18日至22日，以“全球瑰宝·共享未来”为主题的2026热带雨林生态伙伴大会在海南海口举行，来自全球多地的自然保护地管理者、专家和国际组织代表与会，雨林碳治理、生态产品价值…"
