    "description": "在山西太原，有一家特别的潮汕肠粉店。经营小店的是一对听障夫妻，一位热爱烹饪，一位钟情绘画。虽然无法用声音交流，但他们用手语传递心意，用双手经营着属于自己的生活。 为了让从广东远嫁而来的爱人鄞瑛展示自己的厨艺，冯亚斌拿出积蓄开了这家肠粉店；而他自己则开办画室，教聋校的孩子们画画，希望用自己的经历鼓励孩子们勇敢追逐梦想。 除了认真生活，他们也把温暖留给了别人。他们曾为生活有困难的人提供免费餐食，还邀请环卫工人进店吃饭。一碗肠粉虽小，却承载着…",
    "content": "在山西太原，有一家特别的潮汕肠粉店。经营小店的是一对听障夫妻，一位热爱烹饪，一位钟情绘画。虽然无法用声音交流，但他们用手语传递心意，用双手经营着属于自己的生活。 为了让从广东远嫁而来的爱人鄞瑛展示自己的厨艺，冯亚斌拿出积蓄开了这家肠粉店；而他自己则开办画室，教聋校的孩子们画画，希望用自己的经历鼓励孩子们勇敢追逐梦想。 除了认真生活，他们也把温暖留给了别人。他们曾为生活有困难的人提供免费餐食，还邀请环卫工人进店吃饭。一碗肠粉虽小，却承载着一份朴素的善意。 他们听不见彼此的声音，却始终能读懂彼此的心意。一位用画笔表达热…"
