    "pub_date": "2026-11-19 09:52:58",
    "author": "",
    "description": "中新网11月19日电 据中央气象台网站消息，过去一天，冷空气继续南下给我国中东部地区带来显著降温天气。19日早晨监测显示，黄淮、江淮、江汉、江南中东部、华南中西部等地部分地区降温幅度达6～10℃、局地超过12℃；昨天白天，内蒙古、华北、黄淮等地风力强劲，局地阵风达到10～11级。",
    "content": "中新网11月19日电 据中央气象台网站消息，过去一天，冷空气继续南下给我国中东部地区带来显著降温天气。19日早晨监测显示，黄淮、江淮、江汉、江南中东部、华南中西部等地部分地区降温幅度达6～10℃、局地超过12℃；昨天白天，内蒙古、华北、黄淮等地风力强劲，局地阵风达到10～11级。"
