    "content": "台湾的亚太经合组织（APEC）领袖代表施振荣星期三（11月18日）抵达中国大陆深圳出席APEC峰会。台湾代表团透露，施振荣已与13个国家的领导人互动交流。 台湾总统赖清德早前委派科技公司宏碁（Acer）集团创办人暨荣誉董事长施振荣，代表台湾出席APEC会议。 综合《联合报》和《自由时报》报道，台湾代表团的两名不具名成员说，赖清德交付施振荣的任务，是确保台湾的声音被听见，并就科技产业、产业链等议题与各方交流。 代表团成员说，施振荣在APEC会议期间积极与各国领袖接触，截至星期三晚间，已与来自13个国家的领袖互动和交谈…"
