    "title": "伊朗军方称3艘油轮在霍尔木兹海峡东部触雷起火",
    "link": "http://www.news.cn/20261119/266bb7e38a90493680be7f72b68e5de7/c.html",
    "pub_date": "2026-11-19 09:07:12",
    "author": "",
    "description": "新华社德黑兰11月19日电 据伊朗法尔斯通讯社18日晚报道，伊朗军方公共关系部门发表声明说，3艘油轮当天上午在霍尔木兹海峡东部“禁区”航行期间触雷起火，随后停止航行。 声明称，这3艘油轮无视伊朗海军发出的警告，在关闭导航系统的情况下进入禁区，随后触碰水雷并起火。 声明强调，所有船只在霍尔木兹海峡航行时，必须遵守伊朗武装部队公布的规定，事先进行必要协调，选择获准通行的海上航道，并保持导航设备开启。伊朗军方警告，不遵守上述要求的船只可能面临…",
    "content": "新华社德黑兰11月19日电 据伊朗法尔斯通讯社18日晚报道，伊朗军方公共关系部门发表声明说，3艘油轮当天上午在霍尔木兹海峡东部“禁区”航行期间触雷起火，随后停止航行。 声明称，这3艘油轮无视伊朗海军发出的警告，在关闭导航系统的情况下进入禁区，随后触碰水雷并起火。 声明强调，所有船只在霍尔木兹海峡航行时，必须遵守伊朗武装部队公布的规定，事先进行必要协调，选择获准通行的海上航道，并保持导航设备开启。伊朗军方警告，不遵守上述要求的船只可能面临触雷和起火的后果。"
