    "content": "在中美人工智能（AI）竞争加剧、美国收紧科技出口管制的背景下，中共政治局常委、国务院副总理丁薛祥在江西调研时说，实现高质量发展，关键要靠科技创新，并称哪里“卡脖子”就突破哪里。 据中新社报道，丁薛祥星期一至星期三（11月16日至18日）在江西赣州、南昌调研。他首先到于都中央红军长征集结出发地旧址，瞻仰中央红军长征出发纪念碑，参观中央红军长征出发纪念馆。 丁薛祥说，今年是中国工农红军长征胜利90周年，要把伟大长征精神转化为干事创业的强大动力，坚定不移推动高质量发展。 丁薛祥也到江西农业大学猪遗传改良与种质创新全国重点…"
