    "pub_date": "2026-11-19 08:52:30",
    "author": "",
    "description": "新华社济南11月19日电（记者张力元）距今约32.4万年至18.4万年间，在如今广西崇左一带的茂密雨林中，曾生活着直立人。 这一发现来自当地出土的古人类牙齿化石。11月19日零时，山东大学考古学院（文化遗产研究院）联合中国科学院古脊椎动物与古人类研究所等科研机构，在国际学术期刊《自然》在线发表两篇研究论文。相关研究首次在东亚南部亚热带雨林地区确认直立人化石，年代距今约32.4万年至18.4万年，是我国迄今已知年代最晚的直立人化石记录。 …",
    "content": "新华社济南11月19日电（记者张力元）距今约32.4万年至18.4万年间，在如今广西崇左一带的茂密雨林中，曾生活着直立人。 这一发现来自当地出土的古人类牙齿化石。11月19日零时，山东大学考古学院（文化遗产研究院）联合中国科学院古脊椎动物与古人类研究所等科研机构，在国际学术期刊《自然》在线发表两篇研究论文。相关研究首次在东亚南部亚热带雨林地区确认直立人化石，年代距今约32.4万年至18.4万年，是我国迄今已知年代最晚的直立人化石记录。 其中一篇论文的第一作者、山东大学考古学院（文化遗产研究院）副研究员廖卫介绍，这些…"
