    "content": "路透社引述三名知情者说，特朗普政府正考虑要求美国企业公开披露使用中国人工智能（AI）模型的情况，以减少美企对中国AI技术的依赖，同时避免出台可能引起业界或北京不满的新限制措施。 知情者透露，美国财政部和白宫科技政策办公室（OSTP）已讨论这项计划，适用对象包括爱彼迎（Airbnb）等企业。爱彼迎目前使用中国阿里巴巴开发的AI模型通义千问（Qwen），为旗下AI客服助手提供技术支持。 根据这项计划，爱彼迎等企业将须在公司网站上公开披露使用中国AI模型的情况。 目前尚不清楚这项计划是否在特朗普政府内部获得更多支持，以及…"
