    "content": "中国官方通报，中国银行原副行长林景臻涉受贿判刑13年。 据中国最高人民法院微信公号消息，浙江省杭州市中级法院星期三（11月18日）一审公开宣判，以受贿罪对中国银行股份有限公司原党委委员、副行长林景臻判处有期徒刑13年，并处罚金300万元（人民币，下同，58万新元）；对林景臻犯罪所得财物及孳息依法予以追缴，上缴国库。 法院审理查明，林景臻在2015年至2025年间利用担任中国银行（香港）有限公司副总裁、中国银行股份有限公司党委委员、副行长职务上的便利，为有关单位和个人在贷款融资、职工录用等事项上提供帮助，非法收受上述…"
