    "content": "2026年11月19日 本报深圳11月18日电&nbsp;&nbsp;（记者欧阳洁）据海关统计，今年前10月，我国对亚太经合组织（APEC）其他经济体进出口27.08万亿元，同比增长25.4%，高出我国进出口整体增速5.4个百分点，占我国进出口总值的60.4%。其中，我国对APEC其他经济体出口同比增长22.6%，自APEC其他经济体进口同比增长29.1%，高于出口6.5个百分点。 从国别地区看，前10月，我国与20个APEC其他经济体中的14个经济体进出口实现两位数增长。其中，对韩国、越南、秘鲁进出口增速均超过3…"
