    "description": "2026年11月19日 习近平总书记强调，“民心是最大的政治”，“为民造福是最大政绩”。我们党是全心全意为人民服务的马克思主义执政党，管党治党归根结底是为了坚守党的初心使命、性质宗旨，实现好、维护好、发展好最广大人民根本利益。党的二十届五中全会通过的《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》，对“常态化整治群众身边不正之风和腐败问题”作出重要部署，充分体现了以习近平同志为核心的党中央始终坚持以人民为中心的发展思想，把人民…",
    "content": "2026年11月19日 习近平总书记强调，“民心是最大的政治”，“为民造福是最大政绩”。我们党是全心全意为人民服务的马克思主义执政党，管党治党归根结底是为了坚守党的初心使命、性质宗旨，实现好、维护好、发展好最广大人民根本利益。党的二十届五中全会通过的《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》，对“常态化整治群众身边不正之风和腐败问题”作出重要部署，充分体现了以习近平同志为核心的党中央始终坚持以人民为中心的发展思想，把人民放在心中最高位置。我们要深刻领悟“两个确立”的决定性意义、坚决做到“两个维护”，…"
