    "title": "06版 - 从“基础修复”到“巧妙造景”（记者手记）",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202611/19/content_30192025.html",
    "pub_date": "2026-11-19 08:26:04",
    "author": "",
    "description": "2026年11月19日 站在翡翠湖边回顾整个改造历程，能真切感受到资源型地区转型背后的思考与抉择，见证“两山”理念的生动实践。 不少地方开展矿山修复，习惯于简单回填、覆土种树，追求快速完成复绿指标。宝清做法的可贵，在于跳出这套固化路径，尊重矿坑原生地形条件，把开采遗留的“伤疤”转化成景观禀赋。地质治理、生态修复、文旅开发拧成一股绳，实现从“基础修复”向“巧妙造景”的转变。 翡翠湖的实践给资源型地区转型提供了可资借鉴的经验：一片土地的修复…",
    "content": "2026年11月19日 站在翡翠湖边回顾整个改造历程，能真切感受到资源型地区转型背后的思考与抉择，见证“两山”理念的生动实践。 不少地方开展矿山修复，习惯于简单回填、覆土种树，追求快速完成复绿指标。宝清做法的可贵，在于跳出这套固化路径，尊重矿坑原生地形条件，把开采遗留的“伤疤”转化成景观禀赋。地质治理、生态修复、文旅开发拧成一股绳，实现从“基础修复”向“巧妙造景”的转变。 翡翠湖的实践给资源型地区转型提供了可资借鉴的经验：一片土地的修复保护，不仅仅是单纯花钱“补窟窿”。直面历史遗留的“硬骨头”，动脑筋做好生态价值转…"
