    "description": "2026年11月19日 安徽黄山市，前来登山赏景的游客们走进餐馆，大大小小的餐桌上，臭鳜鱼几乎是“标配”。 一盘臭鳜鱼端上桌，用筷子轻轻一拨，鱼肉呈蒜瓣状，肌理间凝着琥珀色。入口的刹那，便是“臭”与“香”的角力：闻着微臭，吃起来香。 黄山市是古徽州“一府六县”的重要区域。作为传承上百年的徽菜代表之一，徽州臭鳜鱼制作技艺于2022年被列入安徽省第六批非物质文化遗产名录。黄山市共有臭鳜鱼加工企业100余家，年加工产值57亿元。 一条臭鳜鱼，…",
    "content": "2026年11月19日 安徽黄山市，前来登山赏景的游客们走进餐馆，大大小小的餐桌上，臭鳜鱼几乎是“标配”。 一盘臭鳜鱼端上桌，用筷子轻轻一拨，鱼肉呈蒜瓣状，肌理间凝着琥珀色。入口的刹那，便是“臭”与“香”的角力：闻着微臭，吃起来香。 黄山市是古徽州“一府六县”的重要区域。作为传承上百年的徽菜代表之一，徽州臭鳜鱼制作技艺于2022年被列入安徽省第六批非物质文化遗产名录。黄山市共有臭鳜鱼加工企业100余家，年加工产值57亿元。 一条臭鳜鱼，如何做成“真香”的大产业？黄山市的答案是：种源自给、聚链成群、标准引领、内外贸一…"
