    "content": "2026年11月19日 上海推出技术经理人联合培养方案 解放日报上海11月18日电&nbsp;&nbsp;（记者余敏之）日前，“上海科技创新与成果转化技术经理人联合培养方案”发布。首期计划招收100名学员，重点面向国资国企、高校院所、科技投资机构及专业成果转化平台。 技术经理人是连接科研与产业的专业人才，既要发现有市场潜力的科技成果、识别企业需求，也要参与成果价值评估、概念验证、融资对接等环节，协调资源，推动科技成果顺畅走向市场。根据联合培养方案，首期培训安排40学时基础课程。 “阅享京津冀”网借一体化服务平台上线…"
