    "description": "2026年11月19日 浙江慈溪市桥头镇是我国棉拖鞋产品主要产地之一。 2024年以来，桥头镇引导企业对接宁波大学科学技术学院、中国科学院宁波材料所，把技改和研发作为拖鞋产业提质的主抓手，在品牌塑造、材料研发、产品设计上联合攻关。 目前，桥头镇11家规上鞋企全部通过数字化改造2.0验收，研发费用占营业收入的比重达2.05%，近3年研发投入逐年提升。 今年1月至8月，全镇拖鞋行业规上企业产值同比增长18.11%。 2026-11-19 0…",
    "content": "2026年11月19日 设计人员在设计新品棉拖鞋。 \"> 工作人员在摆放棉拖鞋样品。 \"> 浙江慈溪市桥头镇是我国棉拖鞋产品主要产地之一。 2024年以来，桥头镇引导企业对接宁波大学科学技术学院、中国科学院宁波材料所，把技改和研发作为拖鞋产业提质的主抓手，在品牌塑造、材料研发、产品设计上联合攻关。 目前，桥头镇11家规上鞋企全部通过数字化改造2.0验收，研发费用占营业收入的比重达2.05%，近3年研发投入逐年提升。 今年1月至8月，全镇拖鞋行业规上企业产值同比增长18.11%。 2026-11-19 00:00:0…"
